import java.util.*;

public class Main {
    int findMaxLength(int[] nums) {
        int n = nums.length;
        int maxLength = 0;
        for (int start = 0; start < n; start++) {
            int zeros = 0, ones = 0;
            for (int end = start; end < n; end++) {
                if (nums[end] == 0) {                                        // extend the subarray by one element
                    zeros++;
                } else {
                    ones++;
                }
                if (zeros == ones) {
                    maxLength = Math.max(maxLength, end - start + 1);
                }
            }
        }
        return maxLength;
    }

