def find_max_length(nums):
    first_seen = {0: -1}                                       # a running sum of 0 was seen before the array starts
    running_sum = 0
    max_length = 0
    for i, num in enumerate(nums):
        running_sum += 1 if num == 1 else -1                       # relabel: 1 stays +1, 0 becomes -1
        if running_sum in first_seen:
            max_length = max(max_length, i - first_seen[running_sum])  # pair with the earliest matching index
        else:
            first_seen[running_sum] = i                                  # record only the first time this sum appears
    return max_length


if __name__ == "__main__":
    print(find_max_length([0, 1, 0, 1]))

