#include <bits/stdc++.h>
using namespace std;

int findMaxLength(vector<int>& nums) {
    unordered_map<int, int> firstSeen;
    firstSeen[0] = -1;                                                 // a running sum of 0 was seen before the array starts
    int runningSum = 0;
    int maxLength = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        runningSum += nums[i] == 1 ? 1 : -1;                               // relabel: 1 stays +1, 0 becomes -1
        if (firstSeen.count(runningSum)) {
            maxLength = max(maxLength, i - firstSeen[runningSum]);            // pair with the earliest matching index
        } else {
            firstSeen[runningSum] = i;                                         // record only the first time this sum appears
        }
    }
    return maxLength;
}

int main() {
    vector<int> nums = {0, 1, 0, 1};
    cout << findMaxLength(nums) << endl;
    return 0;
